parameters.command:
cd /work/output/artifacts/skill-flow-ixp-routing/invoice-extraction/InvoiceExtractionSolution/InvoiceExtraction \
  && uip ixp deployments get-taxonomy --folder-key "c4359cde-55f0-4f0e-9322-c6cdce74ab4c" "idp-benchmark---invoices-c735405a-ixp" --output json 2>&1 | python3 -c "
import json,sys
d=json.load(sys.stdin)
if d.get('Result') == 'Success':
    types = d['Data']['documentTaxonomy']['documentTypes']
    for t in types:
        for f in t.get('fields',[]):
            print(f['fieldName'], '|', f.get('type'))
else:
    print(json.dumps(d, indent=2))
" 2>&1

